from typing import List

def justify_text(text: str, width: int) -> List[str]:
    if width < 1:
        raise ValueError("width must be at least 1")
    normalized = " ".join(text.split())
    if not normalized:
        return []
    words = normalized.split()
    lines_words = []
    current_line = []
    current_len = 0
    for word in words:
        word_len = len(word)
        space_len = 1 if current_line else 0
        if current_len + space_len + word_len <= width:
            current_line.append(word)
            current_len += space_len + word_len
        else:
            if current_line:
                lines_words.append(current_line)
            current_line = [word]
            current_len = word_len
    if current_line:
        lines_words.append(current_line)
    result = []
    for i, line in enumerate(lines_words):
        if i == len(lines_words) - 1 or len(line) == 1:
            line_str = " ".join(line)
            if len(line_str) <= width:
                line_str = line_str.ljust(width)
            result.append(line_str)
        else:
            total_chars = sum(len(w) for w in line)
            if total_chars > width:
                result.append(" ".join(line))
                continue
            total_spaces = width - total_chars
            num_gaps = len(line) - 1
            gap_base = total_spaces // num_gaps
            extra = total_spaces % num_gaps
            res_line = ""
            for j in range(num_gaps):
                res_line += line[j] + " " * (gap_base + (1 if j < extra else 0))
            res_line += line[-1]
            result.append(res_line)
    return result"}}}
