        current_sentence_words.append(word)

        if i == len(words) - 1:
            break

        next_word = words[i+1]
        stripped_word = word
        while stripped_word and stripped_word[-1] in closers:
            stripped_word = stripped_word[:-1]

        if not stripped_word or stripped_word[-1] not in terminators:
            continue

        if word in abbreviations:
            continue

        stripped_leading = word
        while stripped_leading and stripped_leading[0] in openers:
            stripped_leading = stripped_leading[1:]
        if len(stripped_leading) == 2 and stripped_leading[0].isupper() and stripped_leading[1] == '.':
            continue

        if next_word and (next_word[0].isupper() or next_word[0].isdigit() or next_word[0] in openers):
            sentences.append(" ".join(current_sentence_words))
            current_sentence_words = []

    if current_sentence_words:
        sentences.append(" ".join(current_sentence_words))

    return sentences
"}}}
